/* Hello, world — and the whole of what this page does, in one file.
 *
 * Two halves, and they go to two different places.
 *
 * `repeat8` is the kernel. QM minimizes it, and the pane on the right shows
 * what it made of it — in whichever machine you pick, or as the codec, which
 * is the artifact itself. One multiply, on every target that has one.
 *
 * `main` is a driver. The minimizer never sees it: it reads a stream rather
 * than a domain, so minimizing it would report the driver's function instead
 * of the kernel's. Press Run and `main` is compiled on its own with `repeat8`
 * left undefined, and every call it makes is answered by running the artifact:
 *
 *     this file -> QM -> codec -> run
 *
 * So the greeting is ordinary C, and every line after it came out of the
 * minimized program. Type a few characters into the terminal and press Run.
 *
 * `getchar`, `putchar`, `puts`, `print_u64` and `print_hex64` are all there
 * is. The module is freestanding and the first two are its only imports.
 */
#include <stdint.h>

/* One byte, eight times over: the classic broadcast, which is a multiply by
 * 0x0101010101010101 and nothing else. */
uint64_t repeat8(uint8_t c)
{
    return (uint64_t)c * 0x0101010101010101ull;
}

int main(void)
{
    int c;

    puts("Hello, world!");

    while ((c = getchar()) >= 0) {
        uint64_t eight = repeat8((uint8_t)c);

        for (int i = 0; i < 8; ++i)
            putchar((int)((eight >> (8 * i)) & 0xFF));
        putchar('\n');
    }
    return 0;
}

#include <stdint.h>

/* Exclusive prefix population counts of an 8-bit mask, one per byte lane. */
uint64_t ranks8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        r |= (uint64_t)__builtin_popcount(
            m & ((1u << i) - 1)) << (8 * i);

    return r;
}

/* The same kernel as ranks8.c, with a driver — what Run executes.
 *
 * A paste may carry a `main`. The minimizer never sees it: `main` reads a
 * stream rather than a domain, so minimizing it would report the driver's
 * function instead of the kernel's. The two panes show what QM made of
 * `ranks8` alone.
 *
 * Run compiles this `main` on its own, with `ranks8` left undefined, and
 * answers the call by feeding the artifact. So every line the terminal prints
 * came out of the minimized program:
 *
 *     paste -> QM -> codec -> run
 *
 * Type bytes into the terminal and press Run. `getchar`, `putchar`, `puts`,
 * `print_u64` and `print_hex64` are all there is — the module is freestanding
 * and those two of them are its only imports.
 */
#include <stdint.h>

/* Exclusive prefix popcount, one lane per bit: lane i holds how many of the
 * bits below i are set. */
uint64_t ranks8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        r |= (uint64_t)__builtin_popcount(m & ((1u << i) - 1)) << (8 * i);

    return r;
}

int main(void)
{
    int c;

    while ((c = getchar()) >= 0) {
        print_hex64(ranks8((uint8_t)c));
        putchar('\n');
    }
    puts("done");
    return 0;
}

#include <stdint.h>

/* Inclusive prefix popcount.  The boundary condition removes the trailing-zero
 * freedom of ranks8, so the physical constants are uniquely forced. */
uint64_t inclusive_rank8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        r |= (uint64_t)__builtin_popcount(
            m & ((1u << (i + 1)) - 1)) << (8 * i);

    return r;
}

#include <stdint.h>

/* Expand a bit mask to 0x00/0xFF byte lanes.
 * lanecode.h: lc_byte_mask8 — PDEP(m, ONES) * 0xFF */
uint64_t byte_mask8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1)
            r |= 0xFFull << (8 * i);

    return r;
}

#include <stdint.h>

/* Expand each input bit to one four-bit lane containing either 0 or 0xF. */
uint32_t expand_nibbles8(uint8_t m)
{
    uint32_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1u)
            r |= 0xFu << (4 * i);

    return r;
}

#include <stdint.h>

/* Pack the indices of set bits into consecutive byte lanes. */
uint64_t select8(uint8_t m)
{
    uint64_t r = 0;
    unsigned j = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1)
            r |= (uint64_t)i << (8 * j++);

    return r;
}

#include <stdint.h>

/* Indices of the set bits, padded with 0xFF.
 * lanecode.h: lc_shuffle_control8 — ~PEXT(~IOTA, byte_mask8(m)) */
uint64_t shuffle_control8(uint8_t m)
{
    uint64_t r = 0;
    unsigned j = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1)
            r |= (uint64_t)i << (8 * j++);

    while (j < 8)
        r |= 0xFFull << (8 * j++);

    return r;
}

#include <stdint.h>

/* Run starts: a set bit whose left neighbour is clear.
 * lanecode.h: lc_starts — x & ~(x << 1) */
uint64_t starts8(uint8_t m)
{
    uint64_t x = m;

    return x & ~(x << 1);
}

#include <stdint.h>

/* Run ends: a set bit whose right neighbour is clear.  The mirror of starts8,
 * and it lowers to the mirror sequence.
 * lanecode.h: lc_ends — x & ~(x >> 1) */
uint64_t ends8(uint8_t m)
{
    uint64_t x = m;

    return x & ~(x >> 1);
}

#include <stdint.h>

/* Give each set bit the inclusive count of run starts at or below its index. */
uint64_t run_ids8(uint8_t m)
{
    uint8_t starts = m & ~(uint8_t)(m << 1);
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        r |= (uint64_t)__builtin_popcount(
            starts & ((1u << (i + 1)) - 1)) << (8 * i);

    return r;
}

#include <stdint.h>

/* One flag per byte lane, in the high bit — the shape every lanecode.h
 * predicate produces.  The two *_from_spread examples consume it. */
uint64_t spread_high8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1u)
            r |= 0x80ull << (8 * i);

    return r;
}

#include <stdint.h>

/* Collect the high bit of each byte lane into an 8-bit mask. This is the
 * integer analogue of MOVEMASK and can be implemented with PEXT. */
uint8_t mask_from_spread(uint64_t s)
{
    uint8_t m = 0;

    for (unsigned i = 0; i < 8; ++i)
        m |= (uint8_t)(((s >> (8 * i + 7)) & 1ull) << i);

    return m;
}

#include <stdint.h>

/* Widen each per-lane flag to a whole 00/FF byte.
 * lanecode.h: lc_byte_mask_from_spread — (s >> 7) * 0xFF
 *
 * Clear the six unused bits in each lane, shift the flags down, and multiply
 * each remaining bit to fill its byte. */
uint64_t byte_mask_from_spread(uint64_t s)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((s >> (8 * i + 7)) & 1ull)
            r |= 0xFFull << (8 * i);

    return r;
}

#include <stdint.h>

/* Exclusive running parity expanded to 0x00/0xFF byte lanes: the quote state
 * entering each lane.  Normalizes to a carry-less convolution. */
uint64_t quote_state_before8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i) {
        unsigned p = __builtin_popcount(m & ((1u << i) - 1)) & 1;
        r |= (uint64_t)(p * 0xFF) << (8 * i);
    }

    return r;
}

#include <stdint.h>

/* Inclusive running parity, expanded to 0x00/0xFF byte lanes.
 * lanecode.h: lc_prefix_parity_mask8 — PDEP then CLMUL by all-ones */
uint64_t prefix_parity_mask8(uint8_t m)
{
    uint64_t r = 0;
    unsigned p = 0;

    for (unsigned i = 0; i < 8; ++i) {
        p ^= (m >> i) & 1;
        r |= (uint64_t)(p * 0xFF) << (8 * i);
    }

    return r;
}

#include <stdint.h>

/* Inclusive prefix XOR over 64 bits: multiplication by (1+x)^-1 in GF(2)[x].
 * lanecode.h: lc_prefix_xor64 — one CLMUL by all-ones */
uint64_t prefix_xor64(uint64_t x)
{
    uint64_t r = 0;
    uint64_t p = 0;

    for (unsigned i = 0; i < 64; ++i) {
        p ^= (x >> i) & 1;
        r |= p << i;
    }

    return r;
}

#include <stdint.h>

/* Bit positions where the value differs from its left neighbour.
 * lanecode.h: lc_changes — x ^ (x << 1), which is also CLMUL by 3 */
uint64_t changes64(uint64_t x)
{
    return x ^ (x << 1);
}

#include <stdint.h>

/* Spread 16 bits into the even positions of a 32-bit word.  A pure constant
 * GF(2)-linear map: what varies between targets is the representative. */
uint32_t morton_dilate16(uint16_t x)
{
    uint32_t r = 0;

    for (unsigned i = 0; i < 16; ++i)
        if ((x >> i) & 1)
            r |= 1u << (2 * i);

    return r;
}

#include <stdint.h>

/* Gather the even bit positions.
 * lanecode.h: lc_morton_compact_even — PEXT with a 0x5555... mask */
uint8_t morton_compact_even16(uint16_t x)
{
    uint8_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((x >> (2 * i)) & 1)
            r |= (uint8_t)(1u << i);

    return r;
}

#include <stdint.h>

/* Exclusive prefix population counts in sixteen four-bit lanes. */
uint64_t ranks16_nibble(uint16_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 16; ++i)
        r |= (uint64_t)__builtin_popcount(
            m & ((1u << i) - 1)) << (4 * i);

    return r;
}

#include <stdint.h>

/* Exclusive prefix sums of eight byte-lane counts, in place.
 * lanecode.h: lc_block_offsets8 — counts * ONES
 * Requires every prefix to fit in one byte. */
uint64_t block_offsets8(uint64_t counts)
{
    uint64_t r = 0;
    uint64_t acc = 0;

    for (unsigned i = 0; i < 8; ++i) {
        r |= (acc & 0xFF) << (8 * i);
        acc += (counts >> (8 * i)) & 0xFF;
    }

    return r;
}

#include <stdint.h>

/* Which byte lanes are zero — the end-of-string test, exactly rather than
 * approximately.  The well-known (v - ONES) & ~v & HIGH is not this function:
 * a borrow reaches into an adjacent 0x01 lane and reports it as zero.
 * lanecode.h: lc_zero_spread */
uint64_t zero_spread8(uint64_t x)
{
    uint64_t s = 0;

    for (unsigned i = 0; i < 8; ++i)
        if (((x >> (8 * i)) & 0xFF) == 0)
            s |= 0x80ull << (8 * i);

    return s;
}

#include <stdint.h>

/* Which of the eight byte lanes equals a fixed byte, as a 0x80 flag per lane.
 * The comma is the separator a CSV scanner looks for.
 * lanecode.h: LC_EQ_SPREAD — lc_zero_spread(x ^ c * ONES) */
uint64_t eq_spread8(uint64_t x)
{
    uint64_t s = 0;

    for (unsigned i = 0; i < 8; ++i)
        if (((x >> (8 * i)) & 0xFF) == ',')
            s |= 0x80ull << (8 * i);

    return s;
}

#include <stdint.h>

/* Which byte lanes hold a control character, unsigned.  One-sided compare:
 * the interval starts at zero, so only the upper bound is left to test.
 * lanecode.h: LC_LT_SPREAD */
uint64_t lt_spread8(uint64_t x)
{
    uint64_t s = 0;

    for (unsigned i = 0; i < 8; ++i)
        if (((x >> (8 * i)) & 0xFF) < 0x20)
            s |= 0x80ull << (8 * i);

    return s;
}

#include <stdint.h>

/* Which byte lanes hold an ASCII digit.  Both bounds at once: one subtraction
 * per side, and neither borrow leaves the lane it started in.
 * lanecode.h: LC_RANGE_SPREAD */
uint64_t range_spread8(uint64_t x)
{
    uint64_t s = 0;

    for (unsigned i = 0; i < 8; ++i) {
        unsigned b = (unsigned)((x >> (8 * i)) & 0xFF);

        if (b >= '0' && b <= '9')
            s |= 0x80ull << (8 * i);
    }

    return s;
}

#include <stdint.h>

/* Stanford CS107 bit-manipulation exercise: pull a field out of the middle of
 * a word.  Selecting bits is a GF(2)-linear map, so this is one instruction on
 * any target that can extract — and the shift-and-mask pair is not it. */
uint16_t middle_bits_u16(uint16_t x)
{
    return (x >> 4) & 0xFF;
}

#include <stdint.h>

/* Adapted from CS:APP Data Lab logicalNeg: return 1 exactly when x is zero. */
uint32_t logical_neg_i32(uint32_t x)
{
    return x == 0u ? 1u : 0u;
}

#include <stdint.h>

/* Adapted from CS:APP Data Lab isLessOrEqual: compare two signed 32-bit values
 * stored in the high and low halves of one word.
 *
 * A comparison between two parts of a word, not within a lane: the lane
 * predicates in lanecode.h answer eight of these at once and none of them
 * answers this one. */
uint32_t is_less_or_equal_i32(uint64_t ab)
{
    int32_t a = (int32_t)(uint32_t)(ab >> 32);
    int32_t b = (int32_t)(uint32_t)ab;

    return a <= b ? 1u : 0u;
}

#include <stdint.h>

/* MIT 6.172 Lecture 3: select the smaller of two signed 32-bit values. The
 * operands occupy the high and low halves of the input word. */
uint32_t min_i32(uint64_t ab)
{
    int32_t a = (int32_t)(uint32_t)(ab >> 32);
    int32_t b = (int32_t)(uint32_t)ab;

    return (uint32_t)(a < b ? a : b);
}

#include <stdint.h>

/* MIT 6.172 Lecture 3: modular addition by a conditional subtraction. The
 * operands are assumed already reduced; what the function computes is `a + b`,
 * minus the modulus when the sum reached it, and nothing else. */
uint32_t mod_add_u32(uint64_t ab)
{
    uint32_t a = (uint32_t)(ab >> 32);
    uint32_t b = (uint32_t)ab;
    uint64_t s = (uint64_t)a + (uint64_t)b;

    if (s >= 0xFFFFFFFBu) s -= 0xFFFFFFFBu;   /* 2^32 - 5, the largest u32 prime */
    return (uint32_t)s;
}

#include <stdint.h>
/* Adapted from CS:APP Data Lab floatPower2, with x read as a signed byte. */
uint32_t float_power2_bits(uint8_t x)
{
    int32_t e = (int32_t)(int8_t)x + 127;
    if (e <= 0) return 0u;
    if (e >= 255) return 0x7F800000u;
    return (uint32_t)e << 23;
}

#include <stdint.h>

/* Adapted from CS:APP Data Lab floatScale2 for bfloat16 input: the top
 * sixteen bits of a binary32, sign, eight exponent bits and seven of mantissa.
 *
 * The case analysis is the exercise.  A denormal doubles by shifting its
 * mantissa, a normal one by incrementing its exponent, the last finite
 * exponent overflows to infinity, and a NaN comes back untouched — four
 * different programs chosen by one comparison on a field. */
uint16_t float_scale2_bits(uint16_t x)
{
    uint16_t sign = x & 0x8000u;
    unsigned exp = (x >> 7) & 0xFFu;
    unsigned man = x & 0x7Fu;

    if (exp == 0xFFu) return x;                              /* inf or NaN  */
    if (exp == 0u)    return (uint16_t)(sign | (man << 1));  /* denormal    */
    if (exp == 0xFEu) return (uint16_t)(sign | 0x7F80u);     /* overflows   */
    return (uint16_t)(x + 0x80u);                            /* exp + 1     */
}

#include <stdint.h>

/* MIT 6.172 Lecture 3: count the set bits in a 64-bit word. */
uint32_t popcount_u64(uint64_t x)
{
    uint32_t n = 0;

    for (unsigned i = 0; i < 64; ++i)
        n += (uint32_t)((x >> i) & 1u);
    return n;
}

#include <stdint.h>

/* MIT 6.172 Lecture 3: isolate the least significant set bit of x. */
uint64_t least_bit_mask_u64(uint64_t x)
{
    for (unsigned i = 0; i < 64; ++i)
        if ((x >> i) & 1u)
            return (uint64_t)1 << i;
    return 0;
}

#include <stdint.h>

/* MIT 6.172 Lecture 3: the smallest power of two that is not below x. Zero is
 * rounded up to anything, and a value above 2^63 has nothing to round up to,
 * so both answer zero. */
uint64_t round_up_pow2_u64(uint64_t x)
{
    uint64_t n = 0;

    if (x != 0) {
        n = 1;
        for (unsigned i = 0; i < 64; ++i)
            if (n < x) n <<= 1;
    }
    return n;
}

#include <stdint.h>

/* CS:APP Data Lab howManyBits: the fewest bits that can hold x in two's
 * complement.  Zero and minus one both need one; every other value needs its
 * magnitude's width plus a sign bit. */
uint32_t how_many_bits_i32(uint32_t x)
{
    int32_t v = (int32_t)x;
    uint32_t n = 1;

    if (v < 0) v = ~v;
    while (v) { v >>= 1; n += 1; }
    return n;
}

#include <stdint.h>

/* Return the largest of eight unsigned bytes packed in one word. */
uint8_t max_u8x8(uint64_t v)
{
    uint8_t best = 0;

    for (unsigned i = 0; i < 8; ++i) {
        uint8_t lane = (uint8_t)(v >> (8 * i));
        if (lane > best) best = lane;
    }
    return best;
}

#include <stdint.h>

/* Algorithms, 4th Edition, Rabin-Karp: one rolling-hash update. The hash
 * moves up by the radix, the character coming in is added, and the whole thing
 * is reduced modulo the prime.  The running hash is the high byte of the
 * input and the character is the low byte. */
uint16_t rabin_karp_roll(uint16_t hc)
{
    uint32_t h = (uint32_t)(hc >> 8);
    uint32_t c = (uint32_t)(hc & 0xFFu);

    return (uint16_t)((h * 256u + c) % 251u);
}

#include <stdint.h>
/* Algorithms, 4th Edition, key-indexed counting: sort eight 2-bit keys. */
uint16_t counting_sort8_u2(uint16_t v)
{
    int count[4] = {0, 0, 0, 0};
    uint16_t out = 0;
    int at = 0;

    for (int i = 0; i < 8; ++i) count[(v >> (2 * i)) & 3u] += 1;
    for (int key = 0; key < 4; ++key)
        for (int n = 0; n < count[key]; ++n)
            out |= (uint16_t)((uint16_t)key << (2 * at++));
    return out;
}

#include <stdint.h>
/* Algorithms, 4th Edition, KMP: the automaton state after eight text bits for
 * fixed pattern 1011. State is how much of the pattern currently matches. */
uint8_t kmp_scan8_fixed(uint8_t text)
{
    uint8_t state = 0;
    for (int i = 7; i >= 0; --i) {
        uint8_t bit = (uint8_t)((text >> i) & 1u);
        if (state == 0) state = bit ? 1u : 0u;
        else if (state == 1) state = bit ? 1u : 2u;
        else if (state == 2) state = bit ? 3u : 0u;
        else if (state == 3) state = bit ? 4u : 2u;
        else state = bit ? 1u : 2u;
    }
    return state;
}

#include <stdint.h>

/* Adapted from CS:APP Data Lab floatFloat2Int for bfloat16 input: convert to a
 * signed integer by truncating toward zero, and return 0x80000000 when the
 * value is out of range. The exponent determines the shift distance. */
uint32_t float_to_int_bits(uint16_t x)
{
    unsigned sign = (x >> 15) & 1u;
    int exp = (int)((x >> 7) & 0xFFu) - 127;
    uint32_t frac = (uint32_t)(x & 0x7Fu) | 0x80u;
    uint32_t v;

    if (exp < 0) return 0u;
    if (exp > 30) return 0x80000000u;

    if (exp >= 7) v = frac << (exp - 7);
    else          v = frac >> (7 - exp);

    return sign ? (uint32_t)(-(int32_t)v) : v;
}

#include <stdint.h>

/* Adapted from Algorithms, 4th Edition, key-indexed counting: count sixteen
 * two-bit keys and place the four independent counts in four byte lanes. */
uint32_t histogram4_u2x16(uint32_t v)
{
    uint32_t out = 0;

    for (unsigned i = 0; i < 16; ++i)
        out += (uint32_t)1 << (8 * ((v >> (2 * i)) & 3u));
    return out;
}

#include <stdint.h>

/* Floating-point addition is not associative, so this sum has a fixed order.
 *
 * The four addends are the four 16-bit lanes of the input, each read as a
 * bfloat16 and widened exactly into binary64; they are summed strictly left to
 * right in binary64 and the result comes back as its bit pattern.  The
 * exponents range over the whole bfloat16 range, so four addends routinely
 * need more than fifty-three significant bits and every partial sum rounds —
 * which is the whole point, and what makes the order observable.
 *
 * Denormals flush to zero.  Everything here is integer bit surgery on the
 * fields of a binary64, because that is what floating-point addition is once
 * the hardware is taken away.
 *
 * Each partial sum requires a data-dependent normalization shift. */

static uint64_t widen_bf16(uint16_t h)
{
    uint64_t sign = (uint64_t)(h >> 15) << 63;
    unsigned exp = (h >> 7) & 0xFFu;
    uint64_t man = (uint64_t)(h & 0x7Fu) << 45;

    if (exp == 0u) return sign;                       /* zero, or flushed */
    if (exp == 0xFFu) return sign | 0x7FF0000000000000ull | man;
    return sign | ((uint64_t)(exp + 896u) << 52) | man;
}

static uint64_t f64_add(uint64_t a, uint64_t b)
{
    uint64_t swap, ma, mb, sum, sticky;
    unsigned sa, sb, ea, eb, shift;
    int32_t e;

    if ((a & 0x7FFFFFFFFFFFFFFFull) < (b & 0x7FFFFFFFFFFFFFFFull)) {
        swap = a; a = b; b = swap;
    }

    sa = (unsigned)(a >> 63); ea = (unsigned)((a >> 52) & 0x7FFu);
    sb = (unsigned)(b >> 63); eb = (unsigned)((b >> 52) & 0x7FFu);

    if (ea == 0x7FFu) return a;              /* infinity or NaN wins      */
    if (ea == 0u) return 0;                  /* |a| >= |b|, so both zero  */
    if (eb == 0u) return a;                  /* b is zero or flushed      */

    shift = ea - eb;
    if (shift > 56u) return a;               /* b is below the sticky bit */

    ma = (((a & 0x000FFFFFFFFFFFFFull) | 0x0010000000000000ull) << 3);
    mb = (((b & 0x000FFFFFFFFFFFFFull) | 0x0010000000000000ull) << 3);
    sticky = (shift != 0u && (mb & (((uint64_t)1 << shift) - 1u)) != 0u) ? 1u : 0u;
    mb = (mb >> shift) | sticky;

    if (sa == sb) sum = ma + mb;
    else          sum = ma - mb;
    if (sum == 0u) return 0;

    e = (int32_t)ea;
    while (sum >= 0x0100000000000000ull) { sum = (sum >> 1) | (sum & 1u); e += 1; }
    while (sum < 0x0080000000000000ull) { sum <<= 1; e -= 1; }

    if ((sum & 7u) > 4u || ((sum & 7u) == 4u && (sum & 8u) != 0u)) sum += 8u;
    if (sum >= 0x0100000000000000ull) { sum >>= 1; e += 1; }
    sum >>= 3;

    if (e >= 0x7FF) return ((uint64_t)sa << 63) | 0x7FF0000000000000ull;
    if (e <= 0) return (uint64_t)sa << 63;
    return ((uint64_t)sa << 63) | ((uint64_t)e << 52)
         | (sum & 0x000FFFFFFFFFFFFFull);
}

uint64_t strict_sum4_f64(uint64_t v)
{
    uint64_t acc = widen_bf16((uint16_t)v);
    unsigned i;

    for (i = 1; i < 4; ++i)
        acc = f64_add(acc, widen_bf16((uint16_t)(v >> (16 * i))));
    return acc;
}
